import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_ext_typecheck","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_ext_typecheck/index.md","filePath":"api/host/handl_plugin_ext_typecheck/index.md"}`),a={name:`api/host/handl_plugin_ext_typecheck/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-ext-typecheck" tabindex="-1">handl_plugin_ext_typecheck <a class="header-anchor" href="#handl-plugin-ext-typecheck" aria-label="Permalink to “handl_plugin_ext_typecheck”">​</a></h1><p><code>handl-plugin-ext-typecheck</code> — the <code>typecheck</code> capability adapter.</p><p>Exposes the canonical bootstrap typecheck (<code>hnl typecheck</code> / <code>hnl check</code>, ADR-0088 / ADR-0105) through the <code>plugin-ext-*</code> capability seam so a host can dispatch it uniformly alongside <code>fmt</code> and <code>lint</code>.</p><p>The implementation is [<code>plugin::TypecheckPlugin</code>], backed by [<code>handl_kit_prelude::Kit::typecheck_with_prelude</code>] — the <em>same</em> entry point <code>host-cli</code> uses, so the capability path and the direct call cannot drift.</p><h1 id="why-there-is-no-language-payload-unlike-lint" tabindex="-1">Why there is no <code>language</code> payload (unlike <code>lint</code>) <a class="header-anchor" href="#why-there-is-no-language-payload-unlike-lint" aria-label="Permalink to “Why there is no language payload (unlike lint)”">​</a></h1><p>ADR-0124&#39;s language handoff exists because a capability plugin and its caller can assemble <em>different</em> languages while both calling them &quot;canonical&quot; — which is exactly what happened to <code>lint</code> (<code>host-cli</code> used <code>load_canonical_language()</code>, the plugin&#39;s default was <code>lint_language()</code>). <code>typecheck</code> has no such hazard: both sides obtain their language from the single assembly path [<code>Kit::new</code>] (<code>handl_kit_data_prelude::assemble</code>), which is deterministic. Two <code>Kit</code>s built from the same canonical data are therefore identical, so a language payload would carry no information.</p><p>If a non-canonical <code>Language</code> ever needs checking through this capability, the extension point is a <code>language</code> payload field deserialized into [<code>handl_language::Language</code>] and handed to <code>hnl_engine_typecheck::check_module_with_prelude</code> (which <em>does</em> take <code>&amp;Language</code>); that returns diagnostics rather than a synthesized type, so it would be an additive <code>status</code> variant, not a replacement.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-ext-typecheck-1" tabindex="-1"><a href="./handl_plugin_ext_typecheck.html"><code>handl_plugin_ext_typecheck</code></a> <a class="header-anchor" href="#handl-plugin-ext-typecheck-1" aria-label="Permalink to “handl_plugin_ext_typecheck”">​</a></h3><p><em>1 module</em></p><h3 id="plugin" tabindex="-1"><a href="./plugin.html"><code>plugin</code></a> <a class="header-anchor" href="#plugin" aria-label="Permalink to “plugin”">​</a></h3><p><em>1 constant, 1 struct, 1 type alias</em></p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};